void Solver::bump_var(int var, double coeff) {
    // compute increment based on current decay factor
    double inc = var_inc * coeff;
    activity[var] += inc;

    // safeguard against floating point overflow by rescaling all activities
    const double MAX_ACT = 1e120;
    if (activity[var] > MAX_ACT) {
        double scale = 1e-120;
        for (int i = 1; i <= vars; ++i) {
            activity[i] *= scale;
        }
        var_inc *= scale;
    }

    // keep the VSIDS priority queue up‑to‑date
    if (vsids.inHeap(var)) {
        vsids.update(var);
    }
}
